<?php
declare(strict_types=1);
require_once __DIR__.'/../_core/bootstrap.php';require_once __DIR__.'/../_core/CommerceOrders.php';
header('Cache-Control: no-store');header('X-Robots-Tag: noindex, nofollow');header('X-Frame-Options: SAMEORIGIN');
$id=(int)($_GET['id']??0);if(empty($_SESSION['customer_id'])){header('Location: /account/?next='.rawurlencode('/account/order.php?id='.$id));exit;}
$commerce=new \BYPCMS\Core\CommerceOrders($db,$config,BYPCMS_ROOT);
try{$order=$commerce->view($id,(int)$_SESSION['customer_id']);}catch(Throwable $e){http_response_code(404);exit('Заказ не найден. Вернитесь в /account/.');}
$_SESSION['customer_csrf']??=bin2hex(random_bytes(32));$csrf=$_SESSION['customer_csrf'];$user=$auth->user();$available=$commerce->available(!empty($config['app']['debug'])||($user['role']??'')==='owner');
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Заказ №<?= $id ?> — BYPCMS</title><link rel="stylesheet" href="/account/account.css"></head><body><main><header><a href="/">BYPCMS</a><a href="/account/">Мои заказы</a><a href="/contacts/">Контакты и реквизиты</a></header><h1>Заказ №<?= $id ?></h1><section><h2><?= $e($order['edition']==='services'?'Услуги':ucfirst($order['edition'])) ?> · <?= $e($order['domain']) ?></h2><p><?= $order['edition']==='services'?'Работы по согласованному счёту':($order['license_term']==='annual'?'Лицензия на год':'Пожизненная лицензия') ?></p><ul id="order-items"><?php foreach($order['items']['items']as $item):?><li><?= $e($item['name']) ?> · <?= $e(number_format($item['minor']/100,2,',',' ')) ?> ₽</li><?php endforeach ?></ul><p><strong id="order-total"><?= $order['kind']==='inquiry'?'Лицензионная часть:':'Итого:' ?> <?= $e(number_format($order['amount_minor']/100,2,',',' ')) ?> ₽</strong></p><?php if($order['kind']==='inquiry'):?><p class="notice">Заявка сохранена. Состав работ, сроки и точную стоимость согласует продавец. Счёт появится здесь после подготовки; оплатите его после принятия условий.</p><?php endif ?><section id="invoice"></section><p id="test" class="notice" hidden>Тестовый платёж: реального списания не было. Выдаётся тестовая лицензия.</p><dl><dt>Оплата</dt><dd id="payment"></dd><dt>Выдача</dt><dd id="fulfillment"></dd><dt>Уведомление</dt><dd id="mail"></dd></dl><p id="detail"></p><p id="error" class="error" role="alert" hidden></p><p id="notice" class="notice" role="status"></p><div class="buttons"><button id="pay" hidden>Перейти к оплате в ЮKassa</button><button id="check">Проверить статус</button><a id="purchase" class="button" hidden>Открыть покупку и скачать CMS</a></div><p><a href="/account/?next=<?= rawurlencode('/account/order.php?id='.$id) ?>">Войти заново</a> · <a href="/order/">Создать другой заказ</a></p><small>Возврат с платёжной страницы не подтверждает оплату. Банковский перевод и оплату по счёту ЮKassa подтверждает продавец после проверки фактического поступления. Для прежних API-платежей сохраняется серверная сверка с ЮKassa. Ошибка письма не отменяет оплаченную покупку.</small></section><section id="legal" hidden><h2>Условия перед оплатой</h2><form id="legal-form"><label class="check"><input type="checkbox" id="terms" required> Принимаю <a href="/legal/offer/" target="_blank" rel="noopener">условия покупки</a> и <a href="/legal/refunds/" target="_blank" rel="noopener">возврата</a>.</label><label class="check"><input type="checkbox" id="privacy" required> Даю отдельное <a href="/legal/consent/" target="_blank" rel="noopener">согласие на обработку данных</a>. <a href="/legal/privacy/" target="_blank" rel="noopener">Политика</a>.</label><button>Подтвердить условия</button></form></section><section><h2>Возвраты</h2><p id="refund-summary"></p><div id="refund-history"></div><form id="refund-form" hidden><label>Причина обращения<textarea id="refund-reason" required minlength="5" maxlength="2000" rows="4"></textarea></label><button>Отправить обращение владельцу</button></form><p>Обращение не создаёт автоматического возврата и не отключает лицензию. Решение принимает владелец, с учётом условий покупки и закона. <a href="/legal/refunds/">Условия возврата</a>.</p><p id="receipt"></p></section></main><script>
let order=<?= json_encode($order,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE) ?>,csrf=<?= json_encode($csrf) ?>,available=<?= $available?'true':'false' ?>,busy=false,polls=0;
const pay=document.querySelector('#pay'),check=document.querySelector('#check'),error=document.querySelector('#error'),notice=document.querySelector('#notice'),purchase=document.querySelector('#purchase');
const paymentLabels={pending:'Ожидает подтверждения',paid:'Оплата подтверждена',canceled:'Платёж отменён'},fulfillmentLabels={pending:'Готовится после оплаты',ready:'Готово',failed:'Оплата сохранена; выдачу нужно повторить',refunded:'Оплаченные права по заказу возвращены',not_needed:'Услуги: выполнение и приёмка по счёту'},mailLabels={pending:'В очереди',retry:'Ожидает повторной отправки',accepted:'Принято SMTP-сервером',failed:'Ошибка отправки; владелец уведомлён',uncertain:'Статус доставки уточняется',sending:'Отправляется'};
const refundLabels={requested:'Ожидает решения владельца',processing:'Возврат обрабатывается',declined:'Владелец ответил',completed:'Завершена',approved:'Одобрен',creating:'Отправляется',uncertain:'Результат уточняется',pending:'Обрабатывается ЮKassa',succeeded:'Возврат подтверждён',canceled:'Возврат отменён ЮKassa',error:'Запрос отклонён'};
function refundRender(){const refunds=order.refunds;document.querySelector('#legal').hidden=order.legal_accepted||order.payment_state==='paid';document.querySelector('#refund-summary').textContent='Возвращено: '+(refunds.amount_minor/100).toLocaleString('ru-RU')+' ₽.'+(refunds.access_blocked?' Доступ ограничен возвратом.':'')+(refunds.pending?' Ожидается результат ЮKassa.':'');const history=document.querySelector('#refund-history');history.replaceChildren();for(const r of refunds.requests){const p=document.createElement('p');p.textContent='Обращение №'+r.id+': '+(refundLabels[r.state]||r.state)+'. '+r.reason+(r.decision?' Ответ: '+r.decision:'');history.append(p);}for(const r of refunds.rows){const p=document.createElement('p');p.textContent=(r.amount_minor/100).toLocaleString('ru-RU')+' ₽ · '+(refundLabels[r.state]||r.state)+'. '+r.reason;history.append(p);}document.querySelector('#refund-form').hidden=order.payment_state!=='paid'||refunds.amount_minor>=order.amount_minor||refunds.requests.some(r=>['requested','processing'].includes(r.state));document.querySelectorAll('#refund-form button,#legal-form button').forEach(b=>b.disabled=busy);const receipt=document.querySelector('#receipt');receipt.replaceChildren();if(order.receipt?.sale_url){const link=document.createElement('a');link.href=order.receipt.sale_url;link.textContent='Чек Мой налог (ссылка владельца)';link.target='_blank';link.rel='noopener';receipt.append(link);}else if(order.payment_state==='paid')receipt.textContent='Чек формирует и передаёт продавец. По вопросам чека: hello@bypcms.ru.';}
function invoiceRender(){const root=document.querySelector('#invoice');root.replaceChildren();const i=order.invoice;if(!i)return;const title=document.createElement('h2');title.textContent='Счёт '+i.number+' · '+(i.amount_minor/100).toLocaleString('ru-RU')+' ₽';const status=document.createElement('p');status.textContent=i.state==='paid'?'Поступление подтверждено':i.state==='canceled'?'Счёт отменён. Не оплачивайте.':i.expired?'Срок оплаты истёк. Запросите новый счёт.':i.accepted_at?'Счёт принят. Оплатите банковским переводом по реквизитам.':'Проверьте состав, сроки и точную сумму. Примите счёт перед оплатой.';const scope=document.createElement('p');scope.textContent=i.scope;scope.style.whiteSpace='pre-wrap';const link=document.createElement('a');link.href=i.print_url;link.textContent='Открыть счёт с реквизитами / печать / PDF';root.append(title,status,scope,link);if(i.state==='issued'&&!i.expired&&!i.accepted_at){const form=document.createElement('form');const label=document.createElement('label');label.className='check';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.required=true;label.append(checkbox,document.createTextNode('Принимаю состав, точную сумму, результат, сроки и порядок приёмки этого счёта, условия покупки и отдельно даю согласие на обработку данных.'));const terms=document.createElement('p');for(const [text,url]of [['Условия покупки',order.legal.offer],['Возвраты',order.legal.refunds],['Согласие на обработку данных',order.legal.consent]]){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.textContent=text;terms.append(a,document.createTextNode(' · '));}const privacy=document.createElement('label');privacy.className='check';const pc=document.createElement('input');pc.type='checkbox';pc.required=true;privacy.append(pc,document.createTextNode('Отдельно даю согласие на обработку данных для оформления и исполнения заказа.'));label.lastChild.textContent='Принимаю состав, точную сумму, результат, сроки и порядок приёмки этого счёта и условия покупки.';const b=document.createElement('button');b.textContent='Принять счёт';b.disabled=busy;form.append(terms,label,privacy,b);form.onsubmit=e=>{e.preventDefault();void action('invoice.accept',{invoice_id:i.id,legal_version:order.legal.version,accept_terms:checkbox.checked,accept_privacy:pc.checked});};root.append(form);}if(i.state==='issued'&&!i.expired&&i.accepted_at&&i.yookassa_url){const a=document.createElement('a');a.href=i.yookassa_url;a.rel='noopener';a.textContent='Дополнительно: оплатить выставленный счёт ЮKassa';root.append(document.createElement('br'),a);}const note=document.createElement('p');note.textContent='Не оплачивайте дважды. Укажите номер счёта в назначении перевода. Чек формирует продавец в «Мой налог». Выдача лицензии не означает завершения согласованных работ.';root.append(note);}
function render(){refundRender();invoiceRender();const lines=document.querySelector('#order-items');lines.replaceChildren();for(const item of order.items.items){const li=document.createElement('li');li.textContent=item.name+' · '+(item.minor/100).toLocaleString('ru-RU')+' ₽';lines.append(li);}document.querySelector('#order-total').textContent=order.kind==='inquiry'?(order.edition==='services'?'Стоимость услуг согласуется':'Лицензия и модули: '+(order.amount_minor/100).toLocaleString('ru-RU')+' ₽; услуги ещё согласуются'):'Итого: '+(order.amount_minor/100).toLocaleString('ru-RU')+' ₽';document.querySelector('#payment').textContent=order.kind==='inquiry'?'Оплата по согласованию':paymentLabels[order.payment_state]||order.payment_state;document.querySelector('#fulfillment').textContent=fulfillmentLabels[order.fulfillment_state]||order.fulfillment_state;const mail=order.notifications.at(-1);document.querySelector('#mail').textContent=mail?mailLabels[mail.state]||mail.state:'Уведомлений пока нет';document.querySelector('#test').hidden=order.mode!=='test';document.querySelector('#detail').textContent=order.kind==='service'&&order.payment_state==='paid'?'Работы оплачены. Исполнение и приёмка — по согласованному счёту; лицензия не входит.':order.renewed_until?'Продлено до '+order.renewed_until:order.fulfillment_error||order.attempt?.last_error||'';pay.hidden=!!order.invoice||order.kind==='inquiry'||order.kind==='service'||order.payment_state==='paid'||!available;pay.disabled=busy||!order.legal_accepted;check.disabled=busy;check.hidden=false;purchase.hidden=!order.purchase_url;if(order.purchase_url)purchase.href=order.purchase_url;if(!order.invoice&&order.payment_state!=='paid')notice.textContent='Заказ сохранён. Продавец подготовит счёт после проверки состава и реквизитов. Не переводите деньги без актуального счёта.';else notice.textContent=busy?'Проверяем состояние заказа…':'';}
async function action(name,extra={}){if(busy)return;busy=true;error.hidden=true;render();try{const response=await fetch('/commerce/index.php?action='+name,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({id:order.id,...extra}),signal:AbortSignal.timeout(45000)});const result=await response.json();if(!response.ok){if(result.details?.code==='csrf_expired'){const fresh=await fetch('/commerce/index.php?action=bootstrap',{credentials:'same-origin',cache:'no-store'});const data=await fresh.json();if(fresh.ok)csrf=data.csrf;}throw new Error(result.error||'Сервер не подтвердил действие');}if(result.order)order=result.order;else{const fresh=await fetch('/commerce/index.php?action=order&id='+order.id,{credentials:'same-origin',cache:'no-store'});const data=await fresh.json();if(!fresh.ok)throw new Error(data.error);order=data.order;}if(name==='refund.request')document.querySelector('#refund-reason').value='';if(typeof result.payments_available==='boolean')available=result.payments_available;if(name==='pay'&&order.attempt?.confirmation_url&&order.payment_state!=='paid')location.assign(order.attempt.confirmation_url);}catch(e){error.textContent=(e.message||'Не удалось связаться с сервером')+'. Заказ не удалён; повторите проверку статуса.';error.hidden=false;}finally{busy=false;render();}}
document.querySelector('#refund-form').onsubmit=e=>{e.preventDefault();void action('refund.request',{reason:document.querySelector('#refund-reason').value});};document.querySelector('#legal-form').onsubmit=e=>{e.preventDefault();void action('legal.accept',{legal_version:order.legal.version,accept_terms:document.querySelector('#terms').checked,accept_privacy:document.querySelector('#privacy').checked});};
pay.onclick=()=>action('pay');check.onclick=()=>action('sync');render();if(order.attempt&&!(order.payment_state==='paid'&&order.fulfillment_state==='ready'))void action('sync');
const timer=setInterval(()=>{if(++polls>12||order.payment_state==='canceled'||(order.payment_state==='paid'&&order.fulfillment_state==='ready')){clearInterval(timer);return;}if(order.attempt)void action('sync');},5000);
</script></body></html>
